function parseGWEmailTemplate(text) {
  // IMPORTANT: Do NOT include "Date" in keywords - it would corrupt "Visit 2 Date" lines
  // by splitting them. The field() startsWith matching handles "Date:" correctly on its own.
  const keywords = ["Visit 2 Date", "Address", "Appliances and location", "Appliances", "Meter Box", "END OF JOB"];
  let processed = text;
  processed = processed.replace(/([^\n])(PROPERTY\s*\d)/gi, "$1\n$2");
  for (const kw of keywords) {
    const re = new RegExp("([^\n])(" + kw.replace(/[.*+?^${}()|[\]\\]/g, "\\$&") + ")", "g");
    processed = processed.replace(re, "$1\n$2");
  }
  const lines = processed.split(/\r?\n/);
  const records = [];
  let current = null;

  function field(line, label) {
    const prefix = label + ":";
    if (line.trim().toUpperCase().startsWith(prefix.toUpperCase()))
      return line.trim().slice(prefix.length).trim();
    return null;
  }

  function saveCurrent() {
    if (current) records.push(current);
    current = null;
  }

  for (const rawLine of lines) {
    const trimmed = rawLine.trim();
    const stripped = trimmed.replace(/^[=\-\s]+/, "").trim();

    if (stripped.length > 0 && /^PROPERTY\s*\d/i.test(stripped)) {
      saveCurrent();
      current = { project:"IM94R", address:"", date:"", visit1Date:"", visit2Date:"", appliances:[], meterBoxLocation:"" };
      continue;
    }
    if (/^END OF JOB/i.test(stripped)) { saveCurrent(); continue; }
    if (!current) continue;

    const v = (lbl) => field(trimmed, lbl);
    if (v("Address") !== null)                 { current.address = v("Address"); continue; }
    // Visit 2 Date must be checked before Date to avoid partial match
    if (v("Visit 2 Date") !== null)            { current.visit2Date = v("Visit 2 Date"); continue; }
    if (v("Date") !== null)                    { current.date = v("Date"); continue; }
    if (v("Appliances and location") !== null) { current.appliances = v("Appliances and location").split(",").map(s=>s.trim()).filter(Boolean); continue; }
    if (v("Appliances") !== null)              { current.appliances = v("Appliances").split(",").map(s=>s.trim()).filter(Boolean); continue; }
    if (v("Meter Box") !== null)               { current.meterBoxLocation = v("Meter Box"); continue; }
  }
  saveCurrent();
  return records;
}

function GasWorksEmailScreen({ onBack, onHome, onImport }) {
  const [tab, setTab] = useState("send");
  const [propertyCount, setPropertyCount] = useState(1);
  const [copied, setCopied] = useState(false);
  const [emailText, setEmailText] = useState("");
  const [parsed, setParsed] = useState([]);
  const [parseStatus, setParseStatus] = useState("idle");
  const [parseMsg, setParseMsg] = useState("");

  const GW_EMAIL = "lspapandh@gmail.com";
  const GW_BROWN = "#b45309";

  function buildTemplate() {
    let tmpl = "GAS WORKS RECORD REQUEST\n";
    tmpl += "=".repeat(40) + "\n\n";
    tmpl += "Please fill in the details below for each property and send back.\n\n";
    for (let i = 1; i <= propertyCount; i++) {
      tmpl += `PROPERTY ${i}\n`;
      tmpl += "-".repeat(30) + "\n";
      tmpl += "Address: \n";
      tmpl += "Date: \n";
      tmpl += "Visit 2 Date: \n";
      tmpl += "Appliances and location: \n";
      tmpl += "Meter Box: (Inside / Outside)\n";
      tmpl += "\n";
    }
    tmpl += "END OF JOB";
    return tmpl;
  }

  function copyTemplate() {
    navigator.clipboard.writeText(buildTemplate()).then(() => {
      setCopied(true);
      setTimeout(() => setCopied(false), 2000);
    });
  }

  function openMailto() {
    const body = encodeURIComponent(buildTemplate());
    const subject = encodeURIComponent("Gas Works Record Request");
    window.open(`mailto:${GW_EMAIL}?subject=${subject}&body=${body}`, "_blank");
  }

  function doParse() {
    if (!emailText.trim()) return;
    setParseStatus("loading");
    try {
      const results = parseGWEmailTemplate(emailText);
      if (!results || results.length === 0) throw new Error("No PROPERTY blocks found. Make sure the email uses the correct template format.");
      setParsed(results);
      setParseStatus("parsed");
      setParseMsg(`Found ${results.length} propert${results.length===1?"y":"ies"} ready to import.`);
    } catch(e) {
      setParseStatus("error");
      setParseMsg("Error: " + e.message);
    }
  }

  function doImport() {
    const now = new Date();
    const savedSig = (() => { try { return localStorage.getItem(sigStorageKey()) || null; } catch(e) { return null; } })();
    const newRecords = parsed.map((p, i) => {
      const today = new Date().toISOString().slice(0,10);
      // Parse "Appliance-Location" entries e.g. "Boiler-Airing Cupboard, Cooker-Kitchen"
      const appliances = [];
      const applianceLocations = {};
      (p.appliances || []).forEach(entry => {
        const dashIdx = entry.indexOf("-");
        if (dashIdx > 0) {
          const name = entry.slice(0, dashIdx).trim();
          const loc = entry.slice(dashIdx + 1).trim();
          appliances.push(name);
          applianceLocations[name] = loc;
        } else {
          appliances.push(entry);
          applianceLocations[entry] = "";
        }
      });
      return {
        type: "gw",
        gwData: {
          project: p.project || p.address || ("GW-" + (now.getTime() + i)),
          address: p.address || p.project || "",
          date: p.date || today,
          visit1Date: p.date || today,
          visit2Date: p.visit2Date || p.date || today,
          workType: "Kitchen Refurb",
          appliances,
          applianceLocations,
          meterBoxLocation: p.meterBoxLocation || null,
          enablingNotes: "",
          signerName: "Andrew King-Page",
          sigImage: savedSig,
        },
        savedAt: new Date(now.getTime() + i * 1000).toISOString(),
      };
    });
    onImport(newRecords);
    alert(`✅ ${newRecords.length} Gas Works record${newRecords.length===1?"":"s"} created!`);
    onHome();
  }

  const tabStyle = (active) => ({
    flex:1, padding:"11px 0", border:"none", cursor:"pointer", fontWeight:700, fontSize:14,
    fontFamily:"'Segoe UI',sans-serif",
    background: active ? GW_BROWN : "#f0f2f8",
    color: active ? "#fff" : "#666",
    borderRadius: 0,
    transition:"all 0.15s",
  });

  return (
    <div style={{ display:"flex", flexDirection:"column", height:"100vh", background:LIGHT_BG, fontFamily:"'Segoe UI',sans-serif" }}>
      <Header title="Gas Works Email" onBack={onBack} onHome={onHome}/>

      {/* Tabs */}
      <div style={{ display:"flex", flexShrink:0, borderBottom:"2px solid #dde" }}>
        <button style={tabStyle(tab==="send")} onClick={()=>setTab("send")}>📤 Send Template</button>
        <button style={tabStyle(tab==="import")} onClick={()=>setTab("import")}>📥 Import Reply</button>
      </div>

      <div style={{ flex:1, overflowY:"auto", padding:16 }}>

        {tab === "send" && (
          <div>
            <div style={{ background:"#fff", borderRadius:12, padding:16, marginBottom:14, boxShadow:"0 1px 4px rgba(0,0,0,0.06)" }}>
              <p style={{ fontSize:13, color:"#444", marginBottom:14, lineHeight:1.6 }}>
                Choose how many properties to include, then send the template to <strong>{GW_EMAIL}</strong>. Once they fill it in and reply, come back to the <em>Import Reply</em> tab.
              </p>
              <label style={{ fontSize:12, fontWeight:600, color:"#555", marginBottom:6, display:"block" }}>Number of Properties</label>
              <div style={{ display:"flex", alignItems:"center", gap:12, marginBottom:18 }}>
                <button onClick={()=>setPropertyCount(c=>Math.max(1,c-1))} style={{ width:38, height:38, borderRadius:"50%", border:"2px solid #ddd", background:"#f5f5f5", fontSize:20, cursor:"pointer", fontWeight:700 }}>−</button>
                <span style={{ fontSize:24, fontWeight:800, color:GW_BROWN, minWidth:32, textAlign:"center" }}>{propertyCount}</span>
                <button onClick={()=>setPropertyCount(c=>Math.min(20,c+1))} style={{ width:38, height:38, borderRadius:"50%", border:"2px solid #ddd", background:"#f5f5f5", fontSize:20, cursor:"pointer", fontWeight:700 }}>+</button>
              </div>
              <button onClick={openMailto} style={{ width:"100%", background:GW_BROWN, color:"#fff", border:"none", borderRadius:12, padding:"13px", fontSize:15, fontWeight:700, cursor:"pointer", marginBottom:10 }}>
                ✉️ Open in Mail App
              </button>
              <button onClick={copyTemplate} style={{ width:"100%", background:"#fff", color:GW_BROWN, border:`2px solid ${GW_BROWN}`, borderRadius:12, padding:"13px", fontSize:15, fontWeight:700, cursor:"pointer" }}>
                {copied ? "✅ Copied!" : "📋 Copy Template"}
              </button>
            </div>

            <div style={{ background:"#fff", borderRadius:12, padding:14, boxShadow:"0 1px 4px rgba(0,0,0,0.06)" }}>
              <p style={{ fontSize:12, fontWeight:700, color:"#888", marginBottom:8, textTransform:"uppercase", letterSpacing:"0.05em" }}>Template Preview</p>
              <pre style={{ fontSize:12, color:"#333", whiteSpace:"pre-wrap", margin:0, fontFamily:"monospace", lineHeight:1.7 }}>{buildTemplate()}</pre>
            </div>
          </div>
        )}

        {tab === "import" && (
          <div>
            <div style={{ background:"#fff", borderRadius:12, padding:16, marginBottom:14, boxShadow:"0 1px 4px rgba(0,0,0,0.06)", fontSize:13, color:"#444", lineHeight:1.6 }}>
              Paste the completed reply email below and tap <strong>Parse</strong>. A Gas Works record and PDF will be created for each property automatically.
            </div>

            <textarea
              value={emailText}
              onChange={e=>{ setEmailText(e.target.value); setParseStatus("idle"); setParseMsg(""); }}
              placeholder={"Paste the completed email reply here...\n\nPROPERTY 1\n-----\nAddress: 123 High Street\nDate: 2026-03-13\nVisit 1 Date: 2026-03-13\nVisit 2 Date: 2026-03-20\nAppliances and location: Boiler-Airing Cupboard, Cooker-Kitchen\nMeter Box: Outside\n\nPROPERTY 2\n..."}
              style={{ width:"100%", minHeight:160, borderRadius:10, border:"1px solid #ddd", padding:"10px 12px", fontSize:13, fontFamily:"monospace", resize:"vertical", boxSizing:"border-box", marginBottom:10 }}
            />
            <button onClick={doParse} disabled={!emailText.trim()} style={{ width:"100%", background:"#fff", color:GW_BROWN, border:`2px solid ${GW_BROWN}`, borderRadius:12, padding:"12px", fontSize:14, fontWeight:700, cursor:"pointer", marginBottom:14, opacity:!emailText.trim()?0.5:1 }}>
              Parse Email
            </button>

            {parseMsg && (
              <div style={{ background: parseStatus==="error"?"#fff3f3":parseStatus==="parsed"?"#f0fff4":"#f0f4ff", border:`1px solid ${parseStatus==="error"?"#ffcdd2":parseStatus==="parsed"?"#c8e6c9":"#c5cae9"}`, borderRadius:10, padding:"12px 14px", marginBottom:14, fontSize:13, color: parseStatus==="error"?"#c62828":parseStatus==="parsed"?"#2e7d32":"#1a3a8f" }}>
                {parseMsg}
              </div>
            )}

            {parseStatus==="parsed" && parsed.length > 0 && (
              <div>
                {parsed.map((p, i) => (
                  <div key={i} style={{ border:"1px solid #e0e0e0", borderRadius:10, padding:"12px 14px", marginBottom:10, fontSize:13, background:"#fff" }}>
                    <div style={{ fontWeight:700, color:GW_BROWN, marginBottom:4 }}>Property {i+1}: {p.address || "—"}</div>
                    <div style={{ color:"#555" }}>Date: {p.date || "—"}</div>
                    <div style={{ color:"#555" }}>Visit 2: {p.visit2Date || "—"}</div>
                    {p.appliances.length>0 && <div style={{ color:"#555" }}>Appliances: {p.appliances.join(", ")}</div>}
                    {p.meterBoxLocation && <div style={{ color:"#555" }}>Meter Box: {p.meterBoxLocation}</div>}
                  </div>
                ))}
                <button onClick={doImport} style={{ width:"100%", background:"#2e7d32", color:"#fff", border:"none", borderRadius:12, padding:"15px", fontSize:16, fontWeight:700, cursor:"pointer", marginTop:6 }}>
                  ✅ Create {parsed.length} Gas Works Record{parsed.length!==1?"s":""}
                </button>
              </div>
            )}
          </div>
        )}

      </div>
    </div>
  );
}

