                <td style={{ border:"1px solid #999", fontSize:8, textAlign:"left", padding:"1px 3px", overflow:"hidden" }}>{a.model||""}</td>
                {["co2","co","flueType","applianceInspected","combustion","landlordsAppliance","operatingPressure","heatInput","safetyDevices","ventilation","flueVisual","fluePerformance","applianceServiced","applianceSafe"].map((f,fi)=>(
                  <td key={fi} style={{ border:"1px solid #999", fontSize:8, textAlign:"center", padding:"1px 2px" }}>{a[f]||""}</td>
                ))}
