async function createCalendarReminder(certData) {
  let token = getGCalToken();
  if (!token) {
    // Store the pending reminder data so we can create it after OAuth returns
    const reminderDate = new Date();
    reminderDate.setMonth(reminderDate.getMonth() + 11);
    const pendingData = { certData, reminderDate: reminderDate.toISOString() };
    localStorage.setItem("gcal_pending", JSON.stringify(pendingData));
    if (confirm("To add the Google Calendar reminder, you need to sign in with your Google account (akingpage@gmail.com).\n\nTap OK to sign in now.")) {
      startGCalOAuth();
    }
    return;
  }
  await postCalendarEvent(token, certData);
}

async function postCalendarEvent(token, certData, reminderDateOverride) {
  const reminderDate = reminderDateOverride ? new Date(reminderDateOverride) : (() => { const d = new Date(); d.setMonth(d.getMonth() + 11); return d; })();
  const dateStr = reminderDate.toISOString().slice(0, 10);
  const customerName = certData.clientName || certData.instName || "Customer";
  const instAddr = [certData.instAddr1, certData.instAddr2, certData.instAddr3, certData.instPostcode].filter(Boolean).join(", ");
  const tel = certData.instTel || certData.clientTel || "";
  const email = certData.clientEmail || "";
  const event = {
    summary: "Gas Safety Renewal - " + customerName + " - " + (certData.instAddr1 || ""),
    description: "ANNUAL GAS SAFETY RENEWAL REMINDER\n\nCustomer: " + customerName + "\nInstallation Address: " + instAddr + "\nTelephone: " + tel + "\nEmail: " + email + "\n\nPlease contact customer to arrange annual gas safety inspection.",
    start: { date: dateStr },
    end: { date: dateStr },
    reminders: { useDefault: false, overrides: [{ method: "popup", minutes: 540 }, { method: "email", minutes: 540 }] },
  };
  try {
    const resp = await fetch("https://www.googleapis.com/calendar/v3/calendars/primary/events", {
      method: "POST",
      headers: { "Authorization": "Bearer " + token, "Content-Type": "application/json" },
      body: JSON.stringify(event),
    });
    if (resp.status === 401) {
      localStorage.removeItem("gcal_token");
      alert("⚠️ Google Calendar session expired. Please save the next certificate to re-authenticate.");
      return;
    }
    if (!resp.ok) {
      const err = await resp.json();
      throw new Error(err.error?.message || resp.status);
    }
    alert("📅 Google Calendar reminder set for " + reminderDate.toLocaleDateString("en-GB") + "\n\n" + customerName + "\n" + instAddr + (tel ? "\nTel: " + tel : "") + (email ? "\nEmail: " + email : ""));
  } catch(e) {
    alert("⚠️ Could not create Calendar reminder: " + e.message);
  }
}

